mapper.select:
SELECT ob.card_id, ot.card_desc, ob.card_money, ot.card_start_time, oyt.card_num, ot.card_name, ob.user_id, ob.card_code, ob.card_fetch_time, ob.card_media_id, ob.server_id, ob.user_account, ob.card_time, ob.card_froze_money FROM ${database.prefix.payment}hou_pay_card_base ot LEFT JOIN ${database.prefix.payment}hou_pay_card_info ob ON ot.card_id = ob.card_id LEFT JOIN ( SELECT card_id, count(*) card_num FROM ${database.prefix.payment}hou_pay_card_info GROUP BY card_id ) oyt ON oyt.card_id = ob.card_id WHERE 1 = 1
AND ot.card_id = #{param.cardId}
AND ob.user_account = ''
AND ot.card_start_time BETWEEN #{param.returnAddTimeStart} and #{param.returnAddTimeEnd}
